//! Builtin rule catalog embedded at compile time — generated by
//! `build.rs` from `rules/builtin/**/*.sca`. Lets `sast-engine scan`
//! work without an explicit `--rules <DIR>`, mirroring
//! `SCA_PACKAGE_DIR / "rules" / "builtin"` on the Audit side (always
//! resolved automatically, never a CLI argument).
//!
//! **Encrypted at embedding time** (ticket #65): `build.rs` serializes
//! the catalog into a single JSON blob then encrypts it before
//! embedding it (`ENCRYPTED_RULES_BLOB`, via `include_bytes!`) — a
//! `strings` pass on the compiled binary no longer exposes the rules'
//! content. Decrypted on EVERY call to `compile_embedded_rules` (no
//! caching — the cost is dominated by the DSL compilation that
//! follows anyway, already redone on every call before this ticket),
//! with the same "universal" key on the runtime side
//! (`rules_crypto::SALT_DEMO_UNIVERSAL`/`CATALOG_ROOT_SECRET`) as the
//! one used to encrypt on the `build.rs` side.

include!(concat!(env!("OUT_DIR"), "/embedded_rules.rs"));

/// Decrypts `ENCRYPTED_RULES_BLOB` into the catalog's (relative path,
/// content) list — exact mirror of the key derived on the `build.rs`
/// side at encryption time. Panics if the blob is corrupted or the
/// key is wrong: these are build invariants, not recoverable runtime
/// errors (a binary whose catalog doesn't decrypt is a broken binary,
/// not a normal use case).
fn decrypt_embedded_rules() -> Vec<(String, String)> {
    let key = crate::rules::rules_crypto::derive_key(
        crate::rules::rules_crypto::CATALOG_ROOT_SECRET,
        crate::rules::rules_crypto::SALT_DEMO_UNIVERSAL,
        crate::rules::rules_crypto::DEFAULT_INFO,
    );
    let value = crate::rules::rules_crypto::decrypt_blob(ENCRYPTED_RULES_BLOB, &key)
        .expect("catalogue de règles embarqué illisible (clé incorrecte ou blob corrompu)");
    serde_json::from_value(value).expect("format du catalogue de règles embarqué invalide")
}

/// Compiles the embedded builtin rule catalog **entirely in memory**,
/// without ever touching disk: `compile_sca_to_json` takes a string
/// (not a path), so the decrypted catalog (`decrypt_embedded_rules`,
/// already in memory, already sorted by relative path by `build.rs`)
/// can be compiled directly — no need to write it back to disk to
/// reuse `load_rules`. Replaces the former pass through a temporary
/// directory (`extract_to_temp_dir`, removed): no more disk write on
/// first launch, no more risk of a read-only/corrupted tmpdir.
pub fn compile_embedded_rules() -> (Vec<serde_json::Value>, Vec<(std::path::PathBuf, String)>) {
    let mut rules = Vec::new();
    let mut errors = Vec::new();
    for (rel_path, content) in decrypt_embedded_rules() {
        match crate::scan::parser::compile_sca_to_json(&content, &rel_path) {
            Ok(compiled) => rules.extend(compiled),
            Err(e) => errors.push((std::path::PathBuf::from(&rel_path), e.to_string())),
        }
    }
    (rules, errors)
}

/// Set of rule ids actually present in the compiled catalog — ticket
/// #37/spec #26 (compliance-mapping drift safeguard). Reusable by the
/// three safeguards (ISO27001, ASVS, NIST CSF, tickets #37-#39): each
/// compares its own mapping file's keys against this same set, rather
/// than reimplementing the extraction. `BTreeSet` (not `HashSet`):
/// stable order, useful for a reproducible error message if new drift
/// is detected.
pub fn compiled_rule_ids() -> std::collections::BTreeSet<String> {
    compile_embedded_rules()
        .0
        .iter()
        .filter_map(|rule| rule.get("id").and_then(|id| id.as_str()).map(String::from))
        .collect()
}

/// Listing metadata of one embedded rule, for `sast-engine list-rules`.
#[derive(Debug, Clone)]
pub struct RuleListing {
    /// Rule identifier (`rule <id>` in the `.sca` file).
    pub id: String,
    /// Category = the rule's folder (`security`, `arch`, `ux`, `cicd`…),
    /// NOT the `category` field of the rule — same choice as
    /// `Audit/sca/cli.py::_build_rule_metadata` (`parts[1]` of the path
    /// relative to `rules/builtin`).
    pub category_dir: String,
    /// Compiled `risk` block (`{"en": …, "fr": …}`), `Null` if absent.
    pub risk: serde_json::Value,
}

/// One entry per distinct rule id of the embedded catalog, sorted by id
/// — port of `_build_rule_metadata`. A rule id defined in several
/// languages (e.g. `taint_xss` for Python, Java and C#) is listed once,
/// like the Python dict keyed by id; the first file in catalog order
/// wins (Python keeps the last one in `rglob` order, which is
/// filesystem-dependent — a stable choice is preferred here).
pub fn embedded_rule_listing() -> Vec<RuleListing> {
    let mut by_id: std::collections::BTreeMap<String, RuleListing> =
        std::collections::BTreeMap::new();
    for (rel_path, content) in decrypt_embedded_rules() {
        let category_dir = rel_path
            .split(['/', '\\'])
            .nth(1)
            .unwrap_or("security")
            .to_string();
        let Ok(compiled) = crate::scan::parser::compile_sca_to_json(&content, &rel_path) else {
            continue;
        };
        for rule in compiled {
            let Some(id) = rule.get("id").and_then(|v| v.as_str()) else {
                continue;
            };
            by_id.entry(id.to_string()).or_insert_with(|| RuleListing {
                id: id.to_string(),
                category_dir: category_dir.clone(),
                risk: rule.get("risk").cloned().unwrap_or(serde_json::Value::Null),
            });
        }
    }
    by_id.into_values().collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_embedded_rule_listing_uses_folder_category_and_unique_ids() {
        let listing = embedded_rule_listing();
        let ids: std::collections::BTreeSet<&str> = listing.iter().map(|r| r.id.as_str()).collect();
        assert_eq!(ids.len(), listing.len(), "ids are unique");
        let cicd = listing
            .iter()
            .find(|r| r.category_dir == "cicd")
            .expect("YAML CI/CD rules are listed under their folder category");
        assert!(!cicd.id.is_empty());
        assert!(listing.iter().all(|r| !r.category_dir.ends_with(".sca")));
    }

    #[test]
    fn test_embedded_rules_not_empty() {
        let rules = decrypt_embedded_rules();
        assert!(
            rules.len() > 200,
            "catalogue embarqué suspicieusement petit : {} fichiers",
            rules.len()
        );
    }

    #[test]
    fn test_embedded_rules_cover_all_four_languages() {
        let rules = decrypt_embedded_rules();
        for lang in ["python/", "java/", "javascript/", "php/"] {
            assert!(
                rules.iter().any(|(rel, _)| rel.starts_with(lang)),
                "aucune règle embarquée pour {lang}"
            );
        }
    }

    /// Ticket #65: the embedded blob is no longer readable in
    /// plaintext — the same empirical check as the ticket's
    /// acceptance criterion, but in `cargo test` rather than a manual
    /// `strings` pass on the compiled binary.
    #[test]
    fn test_encrypted_rules_blob_does_not_contain_plaintext_rule_content() {
        let blob_str = String::from_utf8_lossy(ENCRYPTED_RULES_BLOB);
        assert!(
            !blob_str.contains("category"),
            "le blob chiffré ne doit exposer aucun texte en clair du catalogue \
             (mot-clé DSL \"category\" trouvé tel quel)"
        );
        assert!(
            !blob_str.contains("severity"),
            "le blob chiffré ne doit exposer aucun texte en clair du catalogue \
             (mot-clé DSL \"severity\" trouvé tel quel)"
        );
    }

    #[test]
    fn test_compile_embedded_rules_no_errors_and_produces_rules() {
        let (rules, errors) = compile_embedded_rules();
        assert!(
            errors.is_empty(),
            "règles embarquées invalides : {errors:?}"
        );
        assert!(
            rules.len() > 200,
            "catalogue compilé suspicieusement petit : {}",
            rules.len()
        );
    }

    #[test]
    fn test_compile_embedded_rules_is_sorted_like_build_rs() {
        // `build.rs` already sorts entries by relative path before
        // serializing/encrypting them — no second sort needed here,
        // unlike `load_rules` (disk, `read_dir` order not
        // guaranteed). Verifies the invariant still holds, without
        // hardcoding a duplicate of it.
        let rel_paths: Vec<String> = decrypt_embedded_rules()
            .into_iter()
            .map(|(rel, _)| rel)
            .collect();
        let mut sorted = rel_paths.clone();
        sorted.sort();
        assert_eq!(rel_paths, sorted);
    }
}
